import{_ as t,c as s,a2 as d,o as a}from"./chunks/framework.DYGJpL-T.js";const u=JSON.parse('{"title":"Events & Telemetry","description":"","frontmatter":{},"headers":[],"relativePath":"reference/events.md","filePath":"reference/events.md","lastUpdated":1795350902000}'),n={name:"reference/events.md"};function i(o,e,r,l,c,h){return a(),s("div",null,e[0]||(e[0]=[d(`<h1 id="events-telemetry" tabindex="-1">Events &amp; Telemetry <a class="header-anchor" href="#events-telemetry" aria-label="Permalink to &quot;Events &amp; Telemetry&quot;">​</a></h1><h2 id="telemetry" tabindex="-1">Telemetry <a class="header-anchor" href="#telemetry" aria-label="Permalink to &quot;Telemetry&quot;">​</a></h2><p>Participating nodes in a Query/Response network topology will broadcast events with structured telemetry for the UI and monitoring applications to consume. The common data-shape encapsulates a way to communicate measurements, events and node-identifying and describing meta data.</p><p>The entry structure and format is encoded as a JSON UTF-8 encoded string payload.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;elements&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;string&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;string|number|boolean&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;OPTIONAL:number&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;uuid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;OPTIONAL:string&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>key</code> and <code>value</code> property pairs are used to encode any measurement. The <code>timestamp</code> is an optional property, that can be used to associate a measurement with a point in time since the EPOCH, in milliseconds. In the telemetry published by the library, <code>timestamp</code> is only present on the throughput samples.</p><p>The <code>uuid</code> property is used to identify the publishing node during its lifetime—effectively creating an aggregate for statistics to present. This means that in practice there are operational metrics which may <em>come and go</em> as well as logical statistics which may pertain to the topology or cluster of nodes. A node gets a new <code>uuid</code> when it restarts.</p><h3 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to &quot;Transport&quot;">​</a></h3><p>Telemetry is published on the shared topic exchange, <code>query-response</code> by default, using the routing key <code>query-response/internal/stats</code>. Each participating node publishes its own message, once per interval.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Property</th></tr></thead><tbody><tr><td>Exchange</td><td><code>query-response</code></td><td><code>queryresponse.exchange.name</code></td></tr><tr><td>Routing key</td><td><code>query-response/internal/stats</code></td><td><code>queryresponse.stats.topic</code></td></tr><tr><td>Reserved key</td><td><code>query-response/internal/telemetry</code></td><td><code>queryresponse.telemetry.topic</code> (UI only)</td></tr><tr><td>Initial delay</td><td><code>7000</code> ms</td><td><code>queryresponse.stats.initial-delay</code></td></tr><tr><td>Publish interval</td><td><code>11000</code> ms</td><td><code>queryresponse.stats.delay</code></td></tr></tbody></table><p>The first message is published <code>initial-delay</code> milliseconds after startup, and subsequent messages are then published every <code>delay</code> milliseconds. Both values are given in milliseconds. See the <a href="./configuration.html">configuration reference</a> for the full set of properties.</p><div class="tip custom-block"><p class="custom-block-title">Vocabulary</p><p>The routing key, the payload keys and the <code>queryresponse.stats.*</code> properties all use the word <em>stats</em>. That is historical naming—the messages carry <em>telemetry</em>. The property names and the <code>internal/stats</code> topic are kept as they are, for compatibility.</p></div><h3 id="table-of-published-telemetry" tabindex="-1">Table of published telemetry <a class="header-anchor" href="#table-of-published-telemetry" aria-label="Permalink to &quot;Table of published telemetry&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Value</th><th>Timestamp</th><th>UUID</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>-</td><td>✓</td><td>Name or identity of the node, or <code>application</code></td></tr><tr><td><code>pid</code></td><td>string</td><td>-</td><td>✓</td><td>Node process id, or <code>-</code></td></tr><tr><td><code>host</code></td><td>string</td><td>-</td><td>✓</td><td>Node hostname, or <code>unknown</code></td></tr><tr><td><code>uptime</code></td><td>string</td><td>-</td><td>✓</td><td>Node uptime, or <code>-</code></td></tr><tr><td><code>only_responses</code></td><td>boolean</td><td>-</td><td>✓</td><td>Whether node has only responded <code>true</code>, or published queries <code>false</code></td></tr><tr><td><code>count_queries</code></td><td>number</td><td>-</td><td>✓</td><td>Number of published queries</td></tr><tr><td><code>count_consumed_responses</code></td><td>number</td><td>-</td><td>✓</td><td>Number of consumed responses</td></tr><tr><td><code>count_published_responses</code></td><td>number</td><td>-</td><td>✓</td><td>Number of published responses</td></tr><tr><td><code>count_fallbacks</code></td><td>number</td><td>-</td><td>✓</td><td>Number of <em>fallbacks</em> (no responses)</td></tr><tr><td><code>max_latency</code></td><td>number</td><td>-</td><td>✓</td><td>Largest recorded time between query and response, in milliseconds</td></tr><tr><td><code>min_latency</code></td><td>number</td><td>-</td><td>✓</td><td>Smallest recorded time between query and response, in milliseconds</td></tr><tr><td><code>avg_latency</code></td><td>number</td><td>-</td><td>✓</td><td>Average time between query and response, in milliseconds</td></tr><tr><td><code>throughput_queries</code></td><td>number</td><td>✓</td><td>✓</td><td>Number of queries published, since last notification</td></tr><tr><td><code>throughput_responses</code></td><td>number</td><td>✓</td><td>✓</td><td>Number of responses published, since last notification</td></tr><tr><td><code>avg_throughput</code></td><td>number</td><td>✓</td><td>✓</td><td>Average throughput, derived by the UI from the throughput samples—<strong>not</strong> published by the library</td></tr></tbody></table><p>The <code>min_latency</code> and <code>max_latency</code> entries are omitted until at least one latency measurement has been recorded.</p><p>The two throughput samples are raw counts since the previous message, that is per publish interval—not per second. Any rate, such as events per second, is derived by the consumer.</p><h3 id="consuming-telemetry" tabindex="-1">Consuming telemetry <a class="header-anchor" href="#consuming-telemetry" aria-label="Permalink to &quot;Consuming telemetry&quot;">​</a></h3><p>The Query/Response UI binds a single anonymous queue to the configured stats topic and to the reserved <code>queryresponse.telemetry.topic</code>, and consumes the messages without acknowledgements. Any other monitoring application can bind its own queue to the stats routing key to receive the same telemetry.</p><p>NOTE: <code>query-response/internal/telemetry</code> is reserved for future use. The UI binds it, but the library does not publish any messages to it yet.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><p>The UI consumes telemetry and broadcasts <code>metrics</code> and <code>nodes</code> updates over the WebSocket at <code>/ws</code>. REST is available for querying (<code>GET /api/v1?q=…</code>) and for node snapshots (<code>GET /api/v0/nodes</code>). The legacy <code>GET /api/v1/nodes</code> endpoint remains available as a last-seen view for existing consumers. Query publishing over the WebSocket is wired in the backend, but the CLI page in the UI is still disabled while its interface is being finished.</p>`,21)]))}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
